package org.apache.commons.jxpath.ri.model.jdom;

import org.jdom.Attribute;
import org.jdom.Content;
import org.jdom.Element;
import org.jdom.Namespace;
import org.junit.Test;

import java.lang.reflect.Method;

import static org.junit.Assert.*;

public class FindEnclosingAttributeTests {

    private static String invokeFindEnclosingAttribute(Object n, String attrName, Namespace ns) {
        try {
            Method m = JDOMNodePointer.class.getDeclaredMethod(
                    "findEnclosingAttribute", Object.class, String.class, Namespace.class);
            m.setAccessible(true);
            return (String) m.invoke(null, n, attrName, ns);
        } catch (Exception e) {
            throw new AssertionError("Invocation failed", e);
        }
    }

    @Test
    public void returnsAttributeFromStartingElementWhenPresent() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute("id", "rootValue", ns);

        assertEquals("rootValue", invokeFindEnclosingAttribute(root, "id", ns));
    }

    @Test
    public void searchesAncestorsAndReturnsFirstFoundValue() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute("id", "rootValue", ns);

        Element child = new Element("child", ns);
        root.addContent(child);

        Element grandChild = new Element("grandChild", ns);
        child.addContent(grandChild);

        assertEquals("rootValue", invokeFindEnclosingAttribute(grandChild, "id", ns));
    }

    @Test
    public void returnsNearestAncestorAttributeWhenMultipleArePresent() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute("id", "rootValue", ns);

        Element child = new Element("child", ns);
        child.setAttribute("id", "childValue", ns);
        root.addContent(child);

        Element grandChild = new Element("grandChild", ns);
        child.addContent(grandChild);

        assertEquals("childValue", invokeFindEnclosingAttribute(grandChild, "id", ns));
    }

    @Test
    public void returnsNullWhenAttributeNotFoundInAnyAncestor() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        Element child = new Element("child", ns);
        root.addContent(child);

        assertNull(invokeFindEnclosingAttribute(child, "missing", ns));
    }

    @Test
    public void returnsNullForNonElementStartingNodeEvenIfParentHasAttribute() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute("id", "rootValue", ns);

        Element child = new Element("child", ns);
        root.addContent(child);

        Content text = new org.jdom.Text("content");
        child.addContent(text);

        assertNull(invokeFindEnclosingAttribute(text, "id", ns));
    }

    @Test
    public void returnsNullForNullStartingNode() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        assertNull(invokeFindEnclosingAttribute(null, "id", ns));
    }

    @Test
    public void usesNamespaceWhenResolvingAttributeName() {
        Namespace ns1 = Namespace.getNamespace("p1", "urn:one");
        Namespace ns2 = Namespace.getNamespace("p2", "urn:two");

        Element root = new Element("root", ns1);
        root.setAttribute("id", "wrongNamespaceValue", ns2);
        root.setAttribute("id", "correctNamespaceValue", ns1);

        assertEquals("correctNamespaceValue", invokeFindEnclosingAttribute(root, "id", ns1));
    }

    @Test
    public void returnsEmptyStringWhenAttributeExistsButValueIsEmpty() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute(new Attribute("id", "", ns));

        assertEquals("", invokeFindEnclosingAttribute(root, "id", ns));
    }

    @Test
    public void doesNotModifyInputStructureAndIsIdempotent() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element root = new Element("root", ns);
        root.setAttribute("id", "rootValue", ns);

        Element child = new Element("child", ns);
        root.addContent(child);

        String first = invokeFindEnclosingAttribute(child, "id", ns);
        String second = invokeFindEnclosingAttribute(child, "id", ns);

        assertEquals("rootValue", first);
        assertEquals(first, second);
        assertEquals(root, child.getParentElement());
        assertEquals("rootValue", root.getAttributeValue("id", ns));
    }
}

