package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.junit.Test;

public class JjFillTokenTests {

    private static class TestableXPathParserTokenManager extends XPathParserTokenManager {
        TestableXPathParserTokenManager(SimpleCharStream stream) {
            super(stream);
        }

        Token callJjFillToken() {
            return super.jjFillToken();
        }
    }

    private static SimpleCharStream streamFor(String input) throws Exception {
        return new SimpleCharStream(new java.io.StringReader(input), 1, 1, input.length());
    }

    private static void setIntField(Object target, String fieldName, int value) throws Exception {
        Field f = target.getClass().getDeclaredField(fieldName);
        f.setAccessible(true);
        f.setInt(target, value);
    }

    private static int getIntField(Object target, String fieldName) throws Exception {
        Field f = target.getClass().getDeclaredField(fieldName);
        f.setAccessible(true);
        return f.getInt(target);
    }

    private static void setStreamState(SimpleCharStream stream, int beginLine, int beginColumn, int endLine, int endColumn)
            throws Exception {
        setIntField(stream, "bufline", 0);
        setIntField(stream, "bufcolumn", 0);
        Field tokenBegin = SimpleCharStream.class.getDeclaredField("tokenBegin");
        tokenBegin.setAccessible(true);
        tokenBegin.setInt(stream, 0);

        Field bufpos = SimpleCharStream.class.getDeclaredField("bufpos");
        bufpos.setAccessible(true);
        bufpos.setInt(stream, 0);

        Field lineField = SimpleCharStream.class.getDeclaredField("line");
        lineField.setAccessible(true);
        lineField.setInt(stream, endLine);

        Field columnField = SimpleCharStream.class.getDeclaredField("column");
        columnField.setAccessible(true);
        columnField.setInt(stream, endColumn);

        Field inBufField = SimpleCharStream.class.getDeclaredField("inBuf");
        inBufField.setAccessible(true);
        inBufField.setInt(stream, 0);

        Field trackLineColumnField = SimpleCharStream.class.getDeclaredField("trackLineColumn");
        trackLineColumnField.setAccessible(true);
        trackLineColumnField.setBoolean(stream, true);

        Field beginLineField = SimpleCharStream.class.getDeclaredField("bufline");
        beginLineField.setAccessible(true);
        int[] bufline = (int[]) beginLineField.get(stream);
        bufline[0] = beginLine;
        bufline[1] = endLine;

        Field beginColumnField = SimpleCharStream.class.getDeclaredField("bufcolumn");
        beginColumnField.setAccessible(true);
        int[] bufcolumn = (int[]) beginColumnField.get(stream);
        bufcolumn[0] = beginColumn;
        bufcolumn[1] = endColumn;
    }

    private static void setTokenizerState(XPathParserTokenManager mgr, int kind) throws Exception {
        Field f = XPathParserTokenManager.class.getDeclaredField("jjmatchedKind");
        f.setAccessible(true);
        f.setInt(mgr, kind);
    }

    @Test
    public void testFillTokenUsesLiteralImageForKeywordToken() throws Exception {
        SimpleCharStream stream = streamFor("or");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 27);

        Token token = mgr.callJjFillToken();

        assertNotNull(token);
        assertEquals(27, token.kind);
        assertEquals("or", token.image);
        assertSame(token, token);
    }

    @Test
    public void testFillTokenUsesStreamImageForTokenWithNullLiteralImage() throws Exception {
        SimpleCharStream stream = streamFor("abc");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 1);

        Token token = mgr.callJjFillToken();

        assertNotNull(token);
        assertEquals(1, token.kind);
        assertEquals("abc", token.image);
    }

    @Test
    public void testFillTokenUsesStreamImageForKindZeroEvenIfLiteralImageEmptyString() throws Exception {
        SimpleCharStream stream = streamFor("");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 0);

        Token token = mgr.callJjFillToken();

        assertNotNull(token);
        assertEquals(0, token.kind);
        assertEquals("", token.image);
    }

    @Test
    public void testFillTokenCopiesPositionInformationFromInputStream() throws Exception {
        String input = "x";
        SimpleCharStream stream = streamFor(input);
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 6);

        Token token = mgr.callJjFillToken();

        assertNotNull(token);
        assertEquals(6, token.kind);
        assertEquals(stream.getBeginLine(), token.beginLine);
        assertEquals(stream.getBeginColumn(), token.beginColumn);
        assertEquals(stream.getEndLine(), token.endLine);
        assertEquals(stream.getEndColumn(), token.endColumn);
    }

    @Test
    public void testFillTokenDoesNotModifyMatchedKindOrStreamPositionState() throws Exception {
        SimpleCharStream stream = streamFor("or");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 27);

        int beginLineBefore = stream.getBeginLine();
        int beginColumnBefore = stream.getBeginColumn();
        int endLineBefore = stream.getEndLine();
        int endColumnBefore = stream.getEndColumn();

        Token token = mgr.callJjFillToken();

        assertEquals(27, getIntField(mgr, "jjmatchedKind"));
        assertEquals(beginLineBefore, stream.getBeginLine());
        assertEquals(beginColumnBefore, stream.getBeginColumn());
        assertEquals(endLineBefore, stream.getEndLine());
        assertEquals(endColumnBefore, stream.getEndColumn());
        assertEquals("or", token.image);
    }

    @Test
    public void testFillTokenCreatesDistinctTokenInstancesForRepeatedCalls() throws Exception {
        SimpleCharStream stream = streamFor("or");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, 27);

        Token first = mgr.callJjFillToken();
        Token second = mgr.callJjFillToken();

        assertNotNull(first);
        assertNotNull(second);
        assertEquals(27, first.kind);
        assertEquals(27, second.kind);
        assertEquals("or", first.image);
        assertEquals("or", second.image);
        if (first == second) {
            throw new AssertionError("jjFillToken must create a new Token object on each invocation");
        }
    }

    @Test(expected = NullPointerException.class)
    public void testFillTokenThrowsWhenInputStreamIsNull() throws Exception {
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(streamFor("a"));
        Field inputField = XPathParserTokenManager.class.getDeclaredField("input_stream");
        inputField.setAccessible(true);
        inputField.set(mgr, null);
        setTokenizerState(mgr, 27);

        mgr.callJjFillToken();
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testFillTokenThrowsForInvalidMatchedKind() throws Exception {
        SimpleCharStream stream = streamFor("a");
        TestableXPathParserTokenManager mgr = new TestableXPathParserTokenManager(stream);
        setTokenizerState(mgr, XPathParserTokenManager.jjstrLiteralImages.length);

        mgr.callJjFillToken();
    }
}

package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.junit.Before;
import org.junit.Test;

public class JjFillTokenTests {

    private static final class TestableXPathParserTokenManager extends XPathParserTokenManager {
        TestableXPathParserTokenManager(SimpleCharStream stream) {
            super(stream);
        }

        Token fillToken() {
            return super.jjFillToken();
        }

        void setMatchedKind(int kind) {
            this.jjmatchedKind = kind;
        }
    }

    private static final class StubSimpleCharStream extends SimpleCharStream {
        private final String image;
        private final int beginLine;
        private final int beginColumn;
        private final int endLine;
        private final int endColumn;
        boolean getImageCalled;

        StubSimpleCharStream(String image, int beginLine, int beginColumn, int endLine, int endColumn) {
            super(new java.io.StringReader(""), 1, 1);
            this.image = image;
            this.beginLine = beginLine;
            this.beginColumn = beginColumn;
            this.endLine = endLine;
            this.endColumn = endColumn;
        }

        @Override
        public String GetImage() {
            getImageCalled = true;
            return image;
        }

        @Override
        public int getBeginLine() {
            return beginLine;
        }

        @Override
        public int getBeginColumn() {
            return beginColumn;
        }

        @Override
        public int getEndLine() {
            return endLine;
        }

        @Override
        public int getEndColumn() {
            return endColumn;
        }
    }

    private TestableXPathParserTokenManager tokenManager;
    private StubSimpleCharStream stream;

    @Before
    public void setUp() {
        stream = new StubSimpleCharStream("STREAM_IMAGE", 3, 7, 3, 12);
        tokenManager = new TestableXPathParserTokenManager(stream);
    }

    @Test
    public void createsTokenWithLiteralImageAndPositionForKnownTokenKind() {
        tokenManager.setMatchedKind(6);

        Token token = tokenManager.fillToken();

        assertEquals(6, token.kind);
        assertEquals("\\57", token.image);
        assertEquals(3, token.beginLine);
        assertEquals(7, token.beginColumn);
        assertEquals(3, token.endLine);
        assertEquals(12, token.endColumn);
        assertTrue("Literal-image token should not consult input stream image", !stream.getImageCalled);
    }

    @Test
    public void usesInputStreamImageWhenNoLiteralImageExists() {
        tokenManager.setMatchedKind(1);

        Token token = tokenManager.fillToken();

        assertEquals(1, token.kind);
        assertEquals("STREAM_IMAGE", token.image);
        assertTrue(stream.getImageCalled);
    }

    @Test
    public void setsTokenFieldsFromInputStreamForBoundaryTokenKindZero() {
        stream = new StubSimpleCharStream("IMG0", 1, 1, 1, 1);
        tokenManager = new TestableXPathParserTokenManager(stream);
        tokenManager.setMatchedKind(0);

        Token token = tokenManager.fillToken();

        assertEquals(0, token.kind);
        assertEquals("", token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void clonesImageForKind27EvenWhenLiteralImageIsPresent() throws Exception {
        tokenManager.setMatchedKind(27);

        Token token = tokenManager.fillToken();

        assertEquals(27, token.kind);
        assertEquals("\\157\\162", token.image);

        String expectedLiteral = XPathParserTokenManager.jjstrLiteralImages[27];
        assertTrue(expectedLiteral != null);
        assertNotSame("Token image must be a distinct String instance for kind 27", expectedLiteral, token.image);
        assertEquals(expectedLiteral, token.image);
    }

    @Test
    public void clonesImageForKind27UsingInputStreamImageWhenLiteralImageIsNull() throws Exception {
        stream = new StubSimpleCharStream("K27_DYNAMIC", 10, 2, 10, 12);
        tokenManager = new TestableXPathParserTokenManager(stream);
        tokenManager.setMatchedKind(getNullLiteralImageKind());

        tokenManager.setMatchedKind(18);
        int kindWithNullLiteral = 18;
        while (kindWithNullLiteral < XPathParserTokenManager.jjstrLiteralImages.length
                && XPathParserTokenManager.jjstrLiteralImages[kindWithNullLiteral] != null) {
            kindWithNullLiteral++;
        }
        tokenManager.setMatchedKind(kindWithNullLiteral);

        Token token = tokenManager.fillToken();

        assertEquals(kindWithNullLiteral, token.kind);
        assertEquals("K27_DYNAMIC", token.image);
        assertEquals(10, token.beginLine);
        assertEquals(2, token.beginColumn);
        assertEquals(10, token.endLine);
        assertEquals(12, token.endColumn);
    }

    @Test
    public void returnsNewTokenInstanceEachCall() {
        tokenManager.setMatchedKind(6);
        Token first = tokenManager.fillToken();
        Token second = tokenManager.fillToken();

        assertTrue(first != second);
        assertEquals(first.kind, second.kind);
        assertEquals(first.image, second.image);
    }

    @Test
    public void doesNotMutateInputStreamStateWhenFillingToken() throws Exception {
        tokenManager.setMatchedKind(6);

        Field beginLineField = SimpleCharStream.class.getDeclaredField("bufline");
        beginLineField.setAccessible(true);

        Token token = tokenManager.fillToken();

        assertEquals(6, token.kind);
        assertEquals(3, token.beginLine);
        assertEquals(7, token.beginColumn);
        assertEquals(3, token.endLine);
        assertEquals(12, token.endColumn);
        assertEquals("STREAM_IMAGE", stream.image);
    }

    private static int getNullLiteralImageKind() throws Exception {
        for (int i = 0; i < XPathParserTokenManager.jjstrLiteralImages.length; i++) {
            if (XPathParserTokenManager.jjstrLiteralImages[i] == null) {
                return i;
            }
        }
        throw new AssertionError("Expected at least one token kind with null literal image");
    }
}

