package org.apache.commons.jxpath.ri.compiler;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.axes.RootContext;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NullPointer;
import org.junit.Assert;
import org.junit.Test;

public class ComputeValueTests {

    @Test
    public void testRelativePathUsesInitialContextAndReturnsSingleNodePointer() {
        TrackingEvalContext context = new TrackingEvalContext();
        LocationPath path = new LocationPath(false, new Step[0]);

        Object result = path.computeValue(context);

        Assert.assertTrue(result instanceof NodePointer);
        Assert.assertEquals(1, context.rootContextCalls);
        Assert.assertEquals(0, context.absoluteRootContextCalls);
        Assert.assertEquals(0, context.nextNodeCalls);
        Assert.assertEquals(0, context.previousCalls);
    }

    @Test
    public void testAbsolutePathUsesAbsoluteRootContextAndReturnsSingleNodePointer() {
        TrackingEvalContext context = new TrackingEvalContext();
        LocationPath path = new LocationPath(true, new Step[0]);

        Object result = path.computeValue(context);

        Assert.assertTrue(result instanceof NodePointer);
        Assert.assertEquals(1, context.rootContextCalls);
        Assert.assertEquals(1, context.absoluteRootContextCalls);
        Assert.assertEquals(0, context.nextNodeCalls);
        Assert.assertEquals(0, context.previousCalls);
    }

    @Test
    public void testComputeValueIsIdempotentForSameContext() {
        TrackingEvalContext context = new TrackingEvalContext();
        LocationPath path = new LocationPath(false, new Step[0]);

        Object first = path.computeValue(context);
        Object second = path.computeValue(context);

        Assert.assertEquals(first, second);
        Assert.assertEquals(2, context.rootContextCalls);
        Assert.assertEquals(0, context.absoluteRootContextCalls);
        Assert.assertEquals(0, context.nextNodeCalls);
        Assert.assertEquals(0, context.previousCalls);
    }

    @Test
    public void testComputeValueDoesNotModifyInputContextState() {
        TrackingEvalContext context = new TrackingEvalContext();
        LocationPath path = new LocationPath(false, new Step[0]);

        path.computeValue(context);

        Assert.assertFalse(context.modified);
        Assert.assertEquals(0, context.nextNodeCalls);
        Assert.assertEquals(0, context.previousCalls);
    }

    @Test
    public void testComputeValueThrowsNullPointerExceptionWhenContextIsNull() {
        LocationPath path = new LocationPath(false, new Step[0]);

        try {
            path.computeValue(null);
            Assert.fail("Expected NullPointerException");
        } catch (NullPointerException expected) {
            // expected
        }
    }

    @Test
    public void testAbsoluteAndRelativePathsProduceDifferentContextAccessPatterns() {
        TrackingEvalContext context1 = new TrackingEvalContext();
        TrackingEvalContext context2 = new TrackingEvalContext();

        LocationPath relative = new LocationPath(false, new Step[0]);
        LocationPath absolute = new LocationPath(true, new Step[0]);

        relative.computeValue(context1);
        absolute.computeValue(context2);

        Assert.assertEquals(1, context1.rootContextCalls);
        Assert.assertEquals(0, context1.absoluteRootContextCalls);

        Assert.assertEquals(1, context2.rootContextCalls);
        Assert.assertEquals(1, context2.absoluteRootContextCalls);
    }

    private static final class TrackingEvalContext extends EvalContext {
        private final RootContext rootContext = new TrackingRootContext();
        private boolean modified;
        private int rootContextCalls;
        private int absoluteRootContextCalls;
        private int nextNodeCalls;
        private int previousCalls;

        private TrackingEvalContext() {
            super(new NullPointer(null, "root"));
        }

        @Override
        public RootContext getRootContext() {
            rootContextCalls++;
            return rootContext;
        }

        @Override
        public int nextNode() {
            nextNodeCalls++;
            modified = true;
            return -1;
        }

        @Override
        public boolean previous() {
            previousCalls++;
            modified = true;
            return false;
        }

        private final class TrackingRootContext extends RootContext {
            private TrackingRootContext() {
                super(TrackingEvalContext.this, new NullPointer(null, "root"));
            }

            @Override
            public RootContext getRootContext() {
                absoluteRootContextCalls++;
                return this;
            }
        }
    }
}

