package org.apache.commons.jxpath.ri.compiler;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.axes.RootContext;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.Iterator;

import static org.junit.Assert.*;

public class ComputeTests {

    private static class TrackingEvalContext extends EvalContext {
        boolean compiled;
        boolean relative;
        int getCurrentNodePointerCalls;
        int getRootContextCalls;
        int getPositionCalls;
        int getSizeCalls;
        int getDocumentOrderCalls;
        int nextNodeCalls;
        int setPositionCalls;
        int getSingleNodePointerCalls;

        TrackingEvalContext() {
            super(null);
        }

        public EvalContext getParentContext() {
            return null;
        }

        public NodePointer getCurrentNodePointer() {
            getCurrentNodePointerCalls++;
            return null;
        }

        public int getCurrentPosition() {
            getPositionCalls++;
            return 1;
        }

        public int getContextNodePosition() {
            return 1;
        }

        public int getDocumentOrder() {
            getDocumentOrderCalls++;
            return 0;
        }

        public int getPosition() {
            getPositionCalls++;
            return 1;
        }

        public boolean nextNode() {
            nextNodeCalls++;
            return false;
        }

        public boolean setPosition(final int position) {
            setPositionCalls++;
            return false;
        }

        public int getSize() {
            getSizeCalls++;
            return 1;
        }

        public boolean isReverse() {
            return false;
        }

        public boolean isAttribute() {
            return false;
        }

        public boolean isChild() {
            return false;
        }

        public boolean isContextDependent() {
            return false;
        }

        public boolean isSet() {
            return false;
        }

        public boolean isValid() {
            return true;
        }

        public void reset() {
        }

        public Iterator iteratePointers() {
            return null;
        }

        public NodePointer getSingleNodePointer() {
            getSingleNodePointerCalls++;
            return null;
        }

        public void setCompiled(final boolean compiled) {
            this.compiled = compiled;
        }

        public boolean isCompiled() {
            return compiled;
        }

        public void setRelative(final boolean relative) {
            this.relative = relative;
        }

        public boolean isRelative() {
            return relative;
        }

        public RootContext getRootContext() {
            getRootContextCalls++;
            return null;
        }
    }

    private static class RecordingLocationPath extends LocationPath {
        EvalContext lastContext;
        int evalStepsCalls;
        EvalContext returnValue = null;

        RecordingLocationPath(final boolean absolute) {
            super(absolute, new Step[0]);
        }

        @Override
        protected EvalContext evalSteps(final EvalContext context) {
            evalStepsCalls++;
            lastContext = context;
            return returnValue;
        }
    }

    @Test
    public void computeDelegatesToEvalStepsAndReturnsItsResultForAbsolutePath() {
        TrackingEvalContext input = new TrackingEvalContext();
        RecordingLocationPath path = new RecordingLocationPath(true);

        EvalContext result = path.compute(input);

        assertSame(path.returnValue, result);
        assertEquals(1, path.evalStepsCalls);
        assertNotNull(path.lastContext);
        assertNotSame(input, path.lastContext);
        assertEquals(1, input.getRootContextCalls);
        assertEquals(0, input.getCurrentNodePointerCalls);
        assertEquals(0, input.getPositionCalls);
        assertEquals(0, input.getSizeCalls);
    }

    @Test
    public void computeDelegatesToEvalStepsAndReturnsItsResultForRelativePath() {
        TrackingEvalContext input = new TrackingEvalContext();
        RecordingLocationPath path = new RecordingLocationPath(false);

        EvalContext result = path.compute(input);

        assertSame(path.returnValue, result);
        assertEquals(1, path.evalStepsCalls);
        assertNotNull(path.lastContext);
        assertNotSame(input, path.lastContext);
        assertEquals(1, input.getRootContextCalls);
        assertEquals(0, input.getCurrentNodePointerCalls);
        assertEquals(0, input.getPositionCalls);
        assertEquals(0, input.getSizeCalls);
    }

    @Test
    public void computeDoesNotModifyTheAbsoluteFlagOrStepsArray() throws Exception {
        RecordingLocationPath path = new RecordingLocationPath(true);
        TrackingEvalContext input = new TrackingEvalContext();

        Field absoluteField = LocationPath.class.getDeclaredField("absolute");
        absoluteField.setAccessible(true);
        boolean absoluteBefore = absoluteField.getBoolean(path);

        Field stepsField = Expression.class.getDeclaredField("steps");
        stepsField.setAccessible(true);
        Object stepsBefore = stepsField.get(path);

        path.compute(input);

        assertEquals(absoluteBefore, absoluteField.getBoolean(path));
        assertSame(stepsBefore, stepsField.get(path));
    }

    @Test(expected = NullPointerException.class)
    public void computePropagatesNullContextToEvalStepsThroughInitialContextCreation() {
        RecordingLocationPath path = new RecordingLocationPath(true);
        path.compute(null);
    }

    @Test
    public void computeUsesSameRootContextBehaviorForRelativeAndAbsolutePathsAccordingToImplementation() {
        TrackingEvalContext input = new TrackingEvalContext();
        RecordingLocationPath absolutePath = new RecordingLocationPath(true);
        RecordingLocationPath relativePath = new RecordingLocationPath(false);

        absolutePath.compute(input);
        relativePath.compute(input);

        assertEquals(2, input.getRootContextCalls);
        assertNotNull(absolutePath.lastContext);
        assertNotNull(relativePath.lastContext);
        assertNotSame(absolutePath.lastContext, relativePath.lastContext);
    }
}

