    public void emptyArrayReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(new String[0]);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void primitiveArrayIsIteratedInOrder() {
        int[] input = new int[] {1, 2, 3};
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertEquals(1, ((Number) it.next()).intValue());
        assertTrue(it.hasNext());
        assertEquals(2, ((Number) it.next()).intValue());
        assertTrue(it.hasNext());
        assertEquals(3, ((Number) it.next()).intValue());
        assertFalse(it.hasNext());

        assertArrayEquals(new int[] {1, 2, 3}, input);
    }

    @Test
    public void objectArrayIsIteratedIncludingNullElements() {
        String[] input = new String[] {"a", null, "c"};
        Iterator it = ValueUtils.iterate(input);

        assertEquals("a", it.next());
        assertNull(it.next());
        assertEquals("c", it.next());
        assertFalse(it.hasNext());

        assertArrayEquals(new String[] {"a", null, "c"}, input);
    }

    @Test
    public void nonEmptyCollectionReturnsItsIterator() {
        List<String> input = new ArrayList<String>(Arrays.asList("x", "y"));
        Iterator it = ValueUtils.iterate(input);

        assertSame(input.iterator().getClass(), it.getClass());
        assertEquals("x", it.next());
        assertEquals("y", it.next());
        assertFalse(it.hasNext());
    }

