import org.junit.Test;

public class AsPathTests {

    private static class SimpleDynaBeanPointer extends DynaBeanPointer {
        public SimpleDynaBeanPointer(NodePointer parent, QName qName, DynaBean dynaBean) {
            super(parent, qName, dynaBean);
        }

        public SimpleDynaBeanPointer(QName qName, DynaBean dynaBean, Locale locale) {
            super(qName, dynaBean, locale);
        }
    }

    private static class SimpleDynaBean implements DynaBean {
        @Override
        public boolean contains(String name, String key) {
            return false;
        }

        @Override
        public Object get(String name) {
            return null;
        }

        @Override
        public Object get(String name, int index) {
            return null;
        }

        @Override
        public Object get(String name, String key) {
            return null;
        }

        @Override
        public DynaClass getDynaClass() {
            return null;
        }

        @Override
        public void remove(String name, String key) {
        }

        @Override
        public void set(String name, Object value) {
        }

        @Override
        public void set(String name, int index, Object value) {
        }

        @Override
        public void set(String name, String key, Object value) {
        }
    }

    @Test
    public void testAsPathReturnsRootWhenParentIsNull() {
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(new QName("bean"), new SimpleDynaBean(), Locale.US);
        assertEquals("/", pointer.asPath());
    }

    @Test
    public void testAsPathIsIdempotentForRootPointer() {
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(new QName("bean"), new SimpleDynaBean(), Locale.US);
        String first = pointer.asPath();
        String second = pointer.asPath();
        assertEquals("/", first);
        assertEquals(first, second);
    }

    @Test
    public void testAsPathDelegatesToSuperclassWhenParentIsNotNull() {
        NodePointer parent = new NullPointer(null, Locale.US);
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(parent, new QName("child"), new SimpleDynaBean());
        assertEquals("/null", pointer.asPath());
    }

    @Test
    public void testAsPathDoesNotModifyParentOrPointerState() {
        NodePointer parent = new NullPointer(null, Locale.US);
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(parent, new QName("child"), new SimpleDynaBean());

        String beforeParent = parent.asPath();
        String first = pointer.asPath();
        String second = pointer.asPath();
        String afterParent = parent.asPath();

        assertEquals("/null", first);
        assertEquals(first, second);
        assertEquals(beforeParent, afterParent);
        assertSame(parent, pointer.getParent());
    }
}
